// cdDil içerik dilini normalize eder.
func cdDil(locale string) string {
	if locale == "" {
		return "tr"
	}
	return locale
}

// cdOGDil Open Graph locale biçimi (dil_BÖLGE).
func cdOGDil(locale string) string {
	switch cdDil(locale) {
	case "tr":
		return "tr_TR"
	case "en":
		return "en_US"
	case "de":
		return "de_DE"
	case "es":
		return "es_ES"
	case "ru":
		return "ru_RU"
	case "fr":
		return "fr_FR"
	case "ar":
		return "ar_AR"
	}
	return cdDil(locale)
}

